"""Load agents.toml and build a Pydantic AI model from model + base_url + key."""

import os
import tomllib
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from pydantic_ai.models import Model
from pydantic_ai.models.google import GoogleModel
from pydantic_ai.models.openai import OpenAIChatModel
from pydantic_ai.providers.google import GoogleProvider
from pydantic_ai.providers.openai import OpenAIProvider

from planworldsimulator_harness.config import AGENTS_FILE


@dataclass(frozen=True)
class AgentConfig:
    name: str
    model: str
    api_key_env: str | None = None
    base_url: str | None = None
    settings: dict[str, Any] = field(default_factory=dict)


def load_agents(path: Path = AGENTS_FILE) -> dict[str, AgentConfig]:
    data = tomllib.loads(path.read_text())
    return {name: AgentConfig(name=name, **entry) for name, entry in data.items()}


def get_agent(name: str, path: Path = AGENTS_FILE) -> AgentConfig:
    agents = load_agents(path)
    if name not in agents:
        raise KeyError(f"unknown agent {name!r}; known: {', '.join(agents)}")
    return agents[name]


def build_model(cfg: AgentConfig) -> Model:
    provider, _, name = cfg.model.partition(":")
    key = os.environ.get(cfg.api_key_env) if cfg.api_key_env else None
    if cfg.api_key_env and not key:
        raise RuntimeError(f"agent {cfg.name!r} needs ${cfg.api_key_env}")
    if provider == "google":
        return GoogleModel(
            name, provider=GoogleProvider(api_key=key, base_url=cfg.base_url)
        )
    if provider == "openai":
        return OpenAIChatModel(
            name, provider=OpenAIProvider(base_url=cfg.base_url, api_key=key)
        )
    raise ValueError(f"agent {cfg.name!r}: provider must be google or openai")

"""Episode budget: hard caps for Pydantic AI plus a neutral status line."""

from dataclasses import dataclass

from pydantic_ai import UsageLimits
from pydantic_ai.usage import RunUsage


@dataclass(frozen=True)
class Budget:
    """One cap for the whole episode. Tokens include thinking tokens."""

    tool_calls: int = 300
    tokens: int = 2_000_000
    seconds: float = 600

    def usage_limits(self) -> UsageLimits:
        return UsageLimits(
            request_limit=None,
            tool_calls_limit=self.tool_calls,
            total_tokens_limit=self.tokens,
        )

    def describe(self) -> str:
        return (
            f"{self.tool_calls} tool calls, {_tokens(self.tokens)} tokens, "
            f"{_clock(self.seconds)} min"
        )

    def status(self, usage: RunUsage, elapsed: float) -> str:
        """Numbers only; no advice, so it does not steer the model."""
        calls = max(0, self.tool_calls - usage.tool_calls)
        tokens = max(0, self.tokens - usage.total_tokens)
        seconds = max(0.0, self.seconds - elapsed)
        return (
            f"Budget left: {calls}/{self.tool_calls} tool calls, "
            f"{_tokens(tokens)}/{_tokens(self.tokens)} tokens, {_clock(seconds)} min."
        )


def _tokens(n: int) -> str:
    return f"{n / 1e6:.1f}M" if n >= 100_000 else f"{n / 1e3:.0f}k"


def _clock(seconds: float) -> str:
    s = int(seconds)
    return f"{s // 60}:{s % 60:02d}"

