"""[base] Voice narrator (decision 0006): spoken intro from ``brief.md``.

Gemini rewrites the brief into a short spoken intro; Gradium text-to-speech turns
it into audio. Both are cached in ``.narration/`` in the world folder, so each world
calls each API once. Keys (``GEMINI_API_KEY``, ``GRADIUM_API_KEY``) stay on the
server. Without keys the intro is the start of ``brief.md`` and there is no audio.
"""

from __future__ import annotations

import os
import re
import threading
from pathlib import Path
from typing import Any

import httpx

ROOT = Path(__file__).resolve().parents[1]
CACHE_DIR = ROOT / ".narration"
KINDS = ("intro",)
INTRO_WORDS = 60
TIMEOUT_S = 60.0

GEMINI_MODEL = "gemini-3.8-flash"
GEMINI_URL = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
GRADIUM_URL = "https://api.gradium.ai/api/post/speech/tts"
GRADIUM_VOICE = "4SZHfMpw-p46Ywgs"  # "Harper": friendly US English flagship voice
AUDIO_FORMAT = "wav"  # plays in every browser
AUDIO_TYPE = "audio/wav"

PROMPT = (
    "You are the narrator of a strategy game. Rewrite the game brief below as a spoken "
    f"intro of about {INTRO_WORDS} words for a new player. Start with 'Welcome to <world name>.' "
    "Explain the setting, the goal and how a turn works. Use short plain sentences, "
    "address the player as 'you', no markdown, lists, code, symbols or arrows. "
    "Reply with the intro text only.\n\nBRIEF:\n"
)

_lock = threading.Lock()  # one generation at a time, so concurrent requests reuse the cache


def narrate(kind: str = "intro") -> dict[str, Any]:
    """Intro text, its sentences and the audio URL (None without audio)."""
    if kind not in KINDS:
        raise ValueError(f"kind must be one of {KINDS}")
    with _lock:
        text = _text(kind)
        has_audio = _audio(kind, text)
    return {"text": text, "sentences": split_sentences(text),
            "audio_url": f"/api/narration/{kind}/audio" if has_audio else None}


def audio_path(kind: str) -> Path | None:
    """Cached audio file for ``kind``, if it exists."""
    path = CACHE_DIR / f"{kind}.{AUDIO_FORMAT}"
    return path if kind in KINDS and path.is_file() else None


def split_sentences(text: str) -> list[str]:
    return [s for s in re.split(r"(?<=[.!?])\s+", text.strip()) if s]


def brief_intro(brief: str, words: int = INTRO_WORDS) -> str:
    """Fallback intro: 'Welcome to <title>.' plus the first sentences of the brief, as plain text."""
    title, body = "", []
    for line in re.sub(r"<!--.*?-->", "", brief, flags=re.S).splitlines():
        line = line.strip()
        if line.startswith("#"):
            title = title or line.lstrip("# ").strip()
        elif line and not line.startswith(("|", "- ", "* ")):  # skip tables and lists
            body.append(line)
    plain = re.sub(r"[`*_]|\s*\([^)]*\)", "", " ".join(body))
    plain = re.sub(r"\s*→\s*", ", ", plain)
    out, count = [f"Welcome to {title}."] if title else [], 0
    for s in split_sentences(plain):
        if out and count + len(s.split()) > words:
            break
        out.append(s)
        count += len(s.split())
    return " ".join(out)


# ---------- pipeline ----------

def _text(kind: str) -> str:
    cached = CACHE_DIR / f"{kind}.txt"
    if cached.is_file():
        return cached.read_text().strip()
    brief = (ROOT / "brief.md").read_text()
    key = os.environ.get("GEMINI_API_KEY", "").strip()
    if not key:
        return brief_intro(brief)
    try:
        text = _gemini(key, PROMPT + brief)
    except (httpx.HTTPError, KeyError, IndexError, ValueError):
        return brief_intro(brief)  # not cached: retry on the next open
    CACHE_DIR.mkdir(exist_ok=True)
    cached.write_text(text + "\n")
    return text


def _audio(kind: str, text: str) -> bool:
    if audio_path(kind):
        return True
    key = os.environ.get("GRADIUM_API_KEY", "").strip()
    if not key:
        return False
    try:
        audio = _gradium(key, text)
    except httpx.HTTPError:
        return False
    if not audio:
        return False
    CACHE_DIR.mkdir(exist_ok=True)
    (CACHE_DIR / f"{kind}.{AUDIO_FORMAT}").write_bytes(audio)
    return True


def _gemini(key: str, prompt: str) -> str:
    res = httpx.post(GEMINI_URL, headers={"x-goog-api-key": key}, timeout=TIMEOUT_S,
                     json={"contents": [{"parts": [{"text": prompt}]}]})
    res.raise_for_status()
    parts = res.json()["candidates"][0]["content"]["parts"]
    text = " ".join(p.get("text", "") for p in parts).strip()
    if not text:
        raise ValueError("empty Gemini reply")
    return re.sub(r"\s+", " ", text)


def _gradium(key: str, text: str) -> bytes:
    res = httpx.post(GRADIUM_URL, headers={"x-api-key": key}, timeout=TIMEOUT_S,
                     json={"text": text, "voice_id": os.environ.get("GRADIUM_VOICE_ID") or GRADIUM_VOICE,
                           "output_format": AUDIO_FORMAT, "only_audio": True})
    res.raise_for_status()
    return res.content
// Voice narrator (decision 0006): spoken intro with captions, bottom right.
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

/** `POST /api/narration` reply; `audio_url` is null when the server has no audio (no keys). */
interface Narration { text: string; sentences: string[]; audio_url: string | null }

const TICK_MS = 100;
const CHARS_PER_S = 15; // caption pace without audio (about 150 words per minute)
const COLLAPSE_MS = 2500;
const DOCK_GAP = 12; // after the intro ends, shrink to the "Replay intro" pill
const BARS = Array.from({ length: 22 }, (_, k) => 0.25 + 0.75 * Math.abs(Math.sin(k * 1.7) * Math.cos(k * 0.45)));

const fmt = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;

/**
 * Caption-first narrator. Captions run on their own clock, synced to the audio
 * while it plays, so the intro also works muted, without audio, or while the
 * browser blocks autoplay (then audio starts on the first click or key press).
 */
export function Narrator() {
  const [intro, setIntro] = useState<Narration | null>(null);
  const [t, setT] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(false);
  const [blocked, setBlocked] = useState(false);
  const [duration, setDuration] = useState<number | null>(null);
  const [open, setOpen] = useState(true);
  const audio = useRef<HTMLAudioElement | null>(null);
  const tRef = useRef(0);
  tRef.current = t;

  const chars = useMemo(() => intro?.sentences.map((s) => s.length) ?? [], [intro]);
  const totalChars = chars.reduce((a, b) => a + b, 0);
  const total = duration ?? Math.max(1, totalChars / CHARS_PER_S);
  const done = intro !== null && t >= total;

  // Load the intro once, then start it.
  useEffect(() => {
    let alive = true;
    fetch("/api/narration", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ kind: "intro" }),
    })
      .then((r) => (r.ok ? (r.json() as Promise<Narration>) : null))
      .then((n) => { if (alive && n?.sentences?.length) setIntro(n); })
      .catch(() => {}); // no server: no narrator
    return () => { alive = false; };
  }, []);

  const startAudio = useCallback((from: number) => {
    const a = audio.current;
    if (!a) return;
    a.currentTime = from;
    a.play().then(() => setBlocked(false)).catch(() => setBlocked(true));
  }, []);

  useEffect(() => {
    if (!intro) return;
    if (intro.audio_url) {
      const a = new Audio(intro.audio_url);
      a.preload = "auto";
      a.addEventListener("loadedmetadata", () => { if (Number.isFinite(a.duration)) setDuration(a.duration); });
      audio.current = a;
      startAudio(0);
    }
    setPlaying(true);
    return () => {
      audio.current?.pause();
      audio.current = null;
    };
  }, [intro, startAudio]);

  // Caption clock: follows the audio while it is audible, runs on its own otherwise.
  useEffect(() => {
    if (!playing) return;
    const timer = setInterval(() => {
      const a = audio.current;
      setT((prev) => (a && !a.paused ? a.currentTime : prev + TICK_MS / 1000));
    }, TICK_MS);
    return () => clearInterval(timer);
  }, [playing]);

  useEffect(() => {
    if (playing && done) setPlaying(false);
  }, [playing, done]);

  useEffect(() => {
    if (!done || playing) return;
    const timer = setTimeout(() => setOpen(false), COLLAPSE_MS);
    return () => clearTimeout(timer);
  }, [done, playing]);

  // Autoplay blocked: start the audio, in sync with the captions, on the first interaction.
  useEffect(() => {
    if (!blocked || !playing) return;
    const unlock = () => startAudio(tRef.current);
    window.addEventListener("pointerdown", unlock, { once: true });
    window.addEventListener("keydown", unlock, { once: true });
    return () => {
      window.removeEventListener("pointerdown", unlock);
      window.removeEventListener("keydown", unlock);
    };
  }, [blocked, playing, startAudio]);

  const replay = useCallback(() => {
    setT(0);
    setOpen(true);
    setPlaying(true);
    startAudio(0);
  }, [startAudio]);

  const togglePlay = useCallback(() => {
    if (playing) {
      audio.current?.pause();
      setPlaying(false);
    } else if (done) {
      replay();
    } else {
      setPlaying(true);
      startAudio(tRef.current);
    }
  }, [playing, done, replay, startAudio]);

  const toggleMute = useCallback(() => {
    setMuted((m) => {
      if (audio.current) audio.current.muted = !m;
      return !m;
    });
  }, []);

  // Sit beside the dock when there is room, otherwise just above it.
  const root = useRef<HTMLDivElement | null>(null);
  useLayoutEffect(() => {
    const el = root.current;
    const host = el?.parentElement;
    const dock = el?.closest(".app")?.querySelector(".app__dock");
    if (!el || !host || !dock) return;
    const place = () => {
      const overlap = dock.getBoundingClientRect().right + DOCK_GAP > el.getBoundingClientRect().left;
      host.classList.toggle("app__narrator--lifted", overlap);
    };
    place();
    const watch = new ResizeObserver(place);
    watch.observe(dock);
    watch.observe(el);
    window.addEventListener("resize", place);
    return () => {
      watch.disconnect();
      window.removeEventListener("resize", place);
    };
  }, [intro, open]);

  if (!intro) return null;

  if (!open) {
    return (
      <div ref={root} className="narrator narrator--idle">
        <button className="narrator__replay" onClick={replay}><ReplayIcon /> Replay intro</button>
        <button className="narrator__logo narrator__logo--lg" onClick={replay} aria-label="Replay intro"><WaveIcon /></button>
      </div>
    );
  }

  // Sentence shown at time t: captions advance in proportion to sentence length.
  let idx = 0;
  for (let acc = 0; idx < chars.length - 1; idx++) {
    acc += chars[idx];
    if (t < (acc / totalChars) * total) break;
  }
  const progress = Math.min(1, t / total);
  const hasAudio = intro.audio_url !== null;
  const audible = hasAudio && playing && !muted && !blocked;
  const status = blocked ? "tap for sound" : muted ? "muted · captions stay on" : hasAudio ? "powered by Gradium" : "captions only";

  return (
    <div ref={root} className="narrator card" role="region" aria-label="Narrator">
      <div className="between">
        <span className="row">
          <span className="narrator__logo"><WaveIcon /></span>
          <span className="insp__head">
            <span className="narrator__name">Narrator · Gradium</span>
            <span className="muted">{status}</span>
          </span>
        </span>
        {blocked ? (
          <button className="narrator__ctl narrator__ctl--pulse" onClick={() => startAudio(tRef.current)} aria-label="Play sound"><SpeakerIcon /></button>
        ) : (
          <span className={`narrator__chip${muted ? " narrator__chip--muted" : ""}`}>{muted ? "muted" : <><i /> intro</>}</span>
        )}
      </div>
      <p className="narrator__caption" aria-live="polite">
        <span key={idx} className="narrator__now">{intro.sentences[idx]}</span>
        {idx < intro.sentences.length - 1 && <span className="narrator__next"> {intro.sentences[idx + 1]}</span>}
      </p>
      <div className="row">
        <button className="narrator__ctl narrator__ctl--ink" onClick={togglePlay} aria-label={playing ? "Pause" : "Play"}>
          {playing ? <PauseIcon /> : <PlayIcon />}
        </button>
        {hasAudio && (
          <button className={`narrator__ctl${muted ? " narrator__ctl--coral" : ""}`} onClick={toggleMute} aria-label={muted ? "Unmute" : "Mute"}>
            <SpeakerIcon off={muted} />
          </button>
        )}
        <button className="narrator__ctl" onClick={replay} aria-label="Replay intro"><ReplayIcon /></button>
        {muted || !hasAudio ? (
          <div className="narrator__dots" />
        ) : (
          <div className={`narrator__wave${audible ? " narrator__wave--live" : ""}`} aria-hidden>
            {BARS.map((h, k) => (
              <i key={k} className={k / BARS.length < progress ? "on" : undefined} style={{ height: `${Math.round(h * 100)}%`, animationDelay: `${(k % 7) * -0.13}s` }} />
            ))}
          </div>
        )}
        <span className="muted narrator__time">{fmt(Math.min(t, total))} / {fmt(total)}</span>
      </div>
    </div>
  );
}

function WaveIcon() {
  return (
    <svg width="18" height="18" viewBox="0 0 18 18" aria-hidden>
      {[5, 10, 14, 8, 12, 6].map((h, k) => (
        <rect key={k} x={2 + k * 2.6} y={9 - h / 2} width="1.6" height={h} rx="0.8" fill="#fff" />
      ))}
    </svg>
  );
}

function PlayIcon() {
  return <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden><path d="M2 1l7 4-7 4z" fill="currentColor" /></svg>;
}

function PauseIcon() {
  return (
    <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden>
      <rect x="2" y="1" width="2" height="8" rx="0.6" fill="currentColor" />
      <rect x="6" y="1" width="2" height="8" rx="0.6" fill="currentColor" />
