// Page layout around the world view. Same in every world; do not edit per world.
import { memo, useCallback, useEffect, useMemo, useState } from "react";
import { sendAction, unqueue, useWorldState } from "./api";
import { agentLook, stopAgent, useAgents, type Play } from "./harness";
import { AgentBanner, FrozenLock } from "./shared/controls/AgentBanner";
import { AgentCursor } from "./shared/controls/AgentCursor";
import { ActionDock } from "./shared/controls/ActionDock";
import { AgentPanel } from "./shared/controls/AgentPanel";
import { Brand } from "./shared/controls/Brand";
import { Discoveries } from "./shared/controls/Discoveries";
import { Goal } from "./shared/controls/Goal";
import { Inspector } from "./shared/controls/Inspector";
import { Narrator } from "./shared/controls/Narrator";
import { Queue } from "./shared/controls/Queue";
import { StoryToast } from "./shared/controls/StoryToast";
import { TopBar } from "./shared/controls/TopBar";
import type { OnAction, QueuedAction, ScoreInfo } from "./shared/types";
import { mockState, toControls, WorldView } from "./World";

// The SVG world is the heaviest part; redraw it only when its props change.
const MemoWorldView = memo(WorldView);
const ERROR_MS = 3000;
const NOBODY: Play = { mode: "you", agent: null };
const ignore: OnAction = () => {};

export default function App() {
  const [state, refresh] = useWorldState(mockState);
  // null = the world's default selection.
  const [selectedId, setSelectedId] = useState<string | null>(null);
  // Dock verb shown as active right away, before the server confirms it.
  const [pending, setPending] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const model = useMemo(() => toControls(state, selectedId), [state, selectedId]);
  const queued = (state as { queued?: QueuedAction[] }).queued ?? [];
  const score = (state as { score?: ScoreInfo }).score;

  // Agent playing (decision 0007): who plays, the harness's agents, frozen controls.
  const play = (state as { play?: Play }).play ?? NOBODY;
  const playing = play.mode === "agent";
  const { agents, offline } = useAgents();
  const look = agentLook(agents, play.agent);

  useEffect(() => setPending(null), [model.dock.active]);
  useEffect(() => {
    if (!error) return;
    const timer = setTimeout(() => setError(null), ERROR_MS);
    return () => clearTimeout(timer);
  }, [error]);

  const run = useCallback(async (id: string, args?: Record<string, unknown>) => {
    const sent = await sendAction(id, { ...args, ...(selectedId ? { target: selectedId } : {}) });
    if (!sent.ok) setError(sent.error ?? "Action rejected");
    await refresh();
    return sent.ok;
  }, [selectedId, refresh]);

  const onAction: OnAction = useCallback((id, args) => void run(id, args), [run]);

  // A dock verb queues that action for the selection, with the inspector's default amount.
  const primary = model.inspector?.primary;
  const verbs = model.dock.verbs;
  const onDock: OnAction = useCallback((id, args) => {
    if (!verbs.some((v) => v.id === id)) return onAction(id, args);
    setPending(id);
    const defaults = primary?.id === id ? { amount: primary.amount } : {};
    void run(id, { ...defaults, ...args }).then((ok) => { if (!ok) setPending(null); });
  }, [verbs, primary, run, onAction]);

  const onRemove = useCallback(async (index: number) => {
    const sent = await unqueue(index);
    if (!sent.ok) setError(sent.error ?? "Could not remove");
    await refresh();
  }, [refresh]);

  const onAgentChanged = useCallback((err?: string) => {
    if (err) setError(err);
    void refresh();
  }, [refresh]);
  const takeOver = useCallback(() => {
    void stopAgent().then((sent) => onAgentChanged(sent.ok ? undefined : sent.error));
  }, [onAgentChanged]);

  const dock = useMemo(() => ({ ...model.dock, active: pending ?? model.dock.active }), [model.dock, pending]);

  return (
    <div className="app">
      <div className="app__glow" />
      <div className="app__brand"><Brand brand={model.brand} /></div>
      <div className="app__top">
        <TopBar topBar={model.topBar} />
        {error ? (
          <div className="story story--coral" role="alert">
            <span className="story__tag">Not queued</span>
            <span>{error}</span>
          </div>
        ) : model.story && <StoryToast story={model.story} />}
      </div>
      <div className="app__world">
        <MemoWorldView state={state} selectedId={selectedId} onSelect={setSelectedId} />
      </div>
      <div className={`app__left${playing ? " frozen" : ""}`}>
        {playing && <FrozenLock />}
        {model.inspector && <Inspector key={model.inspector.title} model={model.inspector} onAction={playing ? ignore : onAction} />}
        <Queue queued={queued} onRemove={(k) => void onRemove(k)} />
        <Discoveries discoveries={model.discoveries} />
      </div>
      <div className="app__right">
        <Goal goal={model.goal} score={score} />
        <AgentPanel agent={model.agent} play={play} agents={agents} offline={offline} week={score?.week ?? 1} onChanged={onAgentChanged} />
      </div>
      <div className={`app__dock${playing ? " frozen" : ""}`}>
        {playing && <FrozenLock />}
        <ActionDock dock={dock} onAction={playing ? ignore : onDock} />
      </div>
      <div className="app__narrator"><Narrator /></div>
      {playing && <AgentBanner look={look} timeLabel={model.topBar.timeLabel} onStop={takeOver} />}
      <AgentCursor look={look} active={playing} onTarget={setSelectedId} />
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

/** One entry of the world's event log (`WS /api/events`). */
interface WorldEvent { seq: number; source: string; kind: string; name: string; args: Record<string, unknown> }

export interface AgentLook { label: string; color: string }

const MOVE_MS = 600;
const MIN_MOVE_MS = 180;
const PULSE_MS = 260;
const READ_MS = 900;
const RECONNECT_MS = 2000;

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/** Round robot face: the agent's badge on the cursor, banner and panel. */
export function RobotBadge({ color, size = 22 }: { color: string; size?: number }) {
  return (
    <svg className="robot" width={size} height={size} viewBox="0 0 22 22" aria-hidden>
      <circle cx="11" cy="11" r="10.5" fill={color} stroke="#fff" strokeWidth="1.5" />
      <line x1="11" y1="2.5" x2="11" y2="5.5" stroke="#fff" strokeWidth="1.4" strokeLinecap="round" />
      <circle cx="11" cy="2.6" r="1.3" fill="#fff" />
      <rect x="5" y="6.5" width="12" height="9.5" rx="3.2" fill="#fff" />
      <circle cx="8.6" cy="11" r="1.5" fill={color} />
      <circle cx="13.4" cy="11" r="1.5" fill={color} />
      <path d="M9 14h4" stroke={color} strokeWidth="1.2" strokeLinecap="round" />
    </svg>
  );
}

/** Where the cursor points at for an element: its centre, in viewport pixels. */
function centre(el: Element): [number, number] {
  const r = el.getBoundingClientRect();
  return [r.left + r.width / 2, r.top + r.height / 2];
}

/** First `[data-target="map:<value>"]` for any string argument (site, target, …). */
function mapTarget(args: Record<string, unknown>): { id: string; el: Element } | null {
  for (const v of Object.values(args)) {
    if (typeof v !== "string") continue;
    const el = document.querySelector(`[data-target="map:${CSS.escape(v)}"]`);
    if (el) return { id: v, el };
  }
  return null;
}

/**
 * Fake cursor that replays the agent's MCP calls (`source: "agent"` events)
 * one after another: move to the site on the map, move to the dock verb,
 * click pulse; `advance` goes to Play; reads show a "reading…" bubble.
 * World-independent: targets are found by `data-target` attributes.
 */
export function AgentCursor({ look, active, onTarget }: { look: AgentLook; active: boolean; onTarget?: (id: string) => void }) {
  const [pos, setPos] = useState<[number, number]>(() => [window.innerWidth / 2, window.innerHeight / 2]);
  const [moveMs, setMoveMs] = useState(MOVE_MS);
  const [bubble, setBubble] = useState<string | null>(null);
  const [pulse, setPulse] = useState(0);
  const queue = useRef<WorldEvent[]>([]);
  const running = useRef(false);
  const onTargetRef = useRef(onTarget);
  onTargetRef.current = onTarget;

  // Taken over: drop what is still queued, so the cursor stops at once.
  useEffect(() => {
    if (!active) queue.current = [];
  }, [active]);

  useEffect(() => {
    let alive = true;
    let ws: WebSocket | null = null;
    let timer: ReturnType<typeof setTimeout>;
    let lastSeq = Number.POSITIVE_INFINITY; // until we know where the log ends, skip the replay

    const move = async (el: Element | null) => {
      if (!el) return;
      const ms = Math.max(MIN_MOVE_MS, MOVE_MS / (1 + 0.35 * queue.current.length));
      setMoveMs(ms);
      setPos(centre(el));
      await sleep(ms);
    };
    const click = async () => {
      setPulse((n) => n + 1);
      await sleep(PULSE_MS);
    };

    const play = async (e: WorldEvent) => {
      if (e.kind === "read" || e.kind === "note") {
        setBubble(e.kind === "note" ? "noting…" : "reading…");
        await sleep(queue.current.length > 2 ? READ_MS / 2 : READ_MS);
        setBubble(null);
      } else if (e.kind === "advance") {
        await move(document.querySelector('[data-target="time:play"]'));
        await click();
      } else if (e.kind === "action") {
        const site = mapTarget(e.args);
        if (site) {
          onTargetRef.current?.(site.id);
          await move(site.el);
          await click();
        }
        await move(document.querySelector(`[data-target="verb:${CSS.escape(e.name)}"]`));
        await click();
      }
    };

    const drain = async () => {
      if (running.current) return;
      running.current = true;
      while (alive && queue.current.length) await play(queue.current.shift()!);
      running.current = false;
    };

    const connect = () => {
      const proto = location.protocol === "https:" ? "wss" : "ws";
      ws = new WebSocket(`${proto}://${location.host}/api/events`);
      ws.onmessage = (msg) => {
        const e = JSON.parse(String(msg.data)) as WorldEvent;
        if (e.seq <= lastSeq) return; // history sent on connect
        lastSeq = e.seq;
        if (e.source !== "agent") return;
        queue.current.push(e);
        void drain();
      };
      ws.onclose = () => { if (alive) timer = setTimeout(start, RECONNECT_MS); };
    };

    const start = async () => {
      try {
        const res = await fetch("/api/events");
        const log = res.ok ? ((await res.json()) as WorldEvent[]) : [];
        lastSeq = log.reduce((m, e) => Math.max(m, e.seq), 0);
      } catch {
        lastSeq = 0;
      }
      if (alive) connect();
    };

    void start();
    return () => {
      alive = false;
      clearTimeout(timer);
      queue.current = [];
      ws?.close();
    };
  }, []);

  if (!active) return null;
  return (
    <div
      className="acursor"
      style={{ transform: `translate(${pos[0]}px, ${pos[1]}px)`, transitionDuration: `${moveMs}ms`, ["--agent" as string]: look.color }}
      aria-hidden
    >
      {pulse > 0 && <span key={pulse} className="acursor__pulse" />}
      <svg className="acursor__arrow" width="22" height="24" viewBox="0 0 22 24">
        <path d="M2 2l17 8.5-7.2 2.1L8.6 20z" fill="var(--agent)" stroke="#fff" strokeWidth="2" strokeLinejoin="round" />
      </svg>
      <span className="acursor__tag">
        <RobotBadge color={look.color} />
        <span className="acursor__name">{look.label}</span>
      </span>
      {bubble && <span className="acursor__bubble">{bubble}</span>}
    </div>
  );
}
import { useEffect, useState } from "react";
import { agentLook, lastRun, startAgent, stopAgent, type AgentInfo, type LastRun, type Play } from "../../harness";
import { Card } from "../primitives/Card";
import { Chip } from "../primitives/Chip";
import { Icon } from "../primitives/Icon";
import type { ControlsModel } from "../types";
import { RobotBadge } from "./AgentCursor";

/** How a run ended (`stopped_by` from the harness), for "Gemini Flash <…>. Your turn." */
const ENDED: Record<string, string> = {
  stopped: "was stopped",
  agent: "finished its turn",
  done: "played to the end",
  limit: "ran out of budget",
  timeout: "hit the time cap",
  error: "failed",
};

const W = 220;
const H = 64;
const PAD = 6;

interface AgentPanelProps {
  agent: ControlsModel["agent"];
  /** Who plays now (`state.play`). */
  play: Play;
  /** Agents from the harness; `offline` while `harness serve` is not running. */
  agents: AgentInfo[];
  offline: boolean;
  /** Current week; from week 2 on the agent continues the player's game. */
  week: number;
  /** After start/stop: refresh the state; `error` when the harness refused. */
  onChanged: (error?: string) => void;
}

/** Agent picker with Start / Stop & take over, experiment score chart, current hypothesis and policy code. */
export function AgentPanel({ agent, play, agents, offline, week, onChanged }: AgentPanelProps) {
  const playing = play.mode === "agent";
  const [choice, setChoice] = useState("");
  const [busy, setBusy] = useState(false);
  const [last, setLast] = useState<LastRun | null>(null);
  const selected = choice || play.agent || agents[0]?.name || "";
  const look = agentLook(agents, playing ? play.agent : selected);

  // When a run ends (stopped, done, out of budget, failed), show how.
  useEffect(() => {
    if (!playing && !offline) void lastRun().then(setLast);
  }, [playing, offline]);

  // One line, so the panel keeps its height (the narrator card sits below it).
  const ended = offline
    ? "Run `pixi run harness serve` to let an agent play."
    : last
      ? `${agentLook(agents, last.agent).label} ${ENDED[last.stopped_by] ?? last.stopped_by}` +
        `${last.agent_steps != null ? ` after ${last.agent_steps} weeks` : ""}${last.error ? ` (${last.error})` : ""}. Your turn.`
      : null;

  const toggle = async () => {
    setBusy(true);
    const sent = playing ? await stopAgent() : await startAgent(selected);
    setBusy(false);
    onChanged(sent.ok ? undefined : sent.error);
  };

  const slots = Math.max(2, agent.slots);
  const x = (k: number) => PAD + (k / (slots - 1)) * (W - 2 * PAD);
  const y = (s: number) => H - PAD - Math.max(0, Math.min(1, s)) * (H - 2 * PAD);
  const line = agent.scores.map((s, k) => `${x(k).toFixed(1)},${y(s).toFixed(1)}`).join(" ");

  return (
    <Card>
      <div className="between">
        <span className="row">
          <i className="agent__dot" />
          <span className="title">Agent</span>
        </span>
        <Chip tone="violet">{agent.experiment}</Chip>
      </div>
      <div className="agentpick" style={{ ["--agent" as string]: look.color }}>
        <label className="agentpick__select">
          <RobotBadge color={look.color} size={20} />
          <select
            aria-label="Agent"
            value={playing ? play.agent ?? "" : selected}
            disabled={playing || offline || busy || agents.length === 0}
            onChange={(e) => setChoice(e.target.value)}
          >
            {agents.length === 0 && <option value="">{offline ? "Harness offline" : "No agents"}</option>}
            {agents.map((a) => <option key={a.name} value={a.name}>{a.label}</option>)}
          </select>
        </label>
        {playing ? (
          <button className="btn agentpick__stop" disabled={busy} onClick={() => void toggle()}>
            <Icon name="pause" size={12} />
            Stop
          </button>
        ) : (
          <button className="btn agentpick__start" disabled={busy || offline || !selected} onClick={() => void toggle()}>
            <Icon name="play" size={12} />
            {last || week > 1 ? "Continue" : "Start"}
          </button>
        )}
      </div>
      {!playing && ended && <div className="muted agent__hint" title={ended}>{ended}</div>}
      <div className="chart">
        <div className="between">
          <span className="caps">Score / experiment</span>
          <span className="muted">baseline {agent.baseline.toFixed(2)}</span>
        </div>
        <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} preserveAspectRatio="none" aria-hidden>
          <line x1={PAD} x2={W - PAD} y1={y(agent.baseline)} y2={y(agent.baseline)} stroke="var(--dim)" strokeWidth="1.2" strokeDasharray="4 3" />
          <polyline points={line} fill="none" stroke="var(--violet)" strokeWidth="2" strokeLinejoin="round" />
          {agent.scores.map((s, k) => (
            <circle key={k} cx={x(k)} cy={y(s)} r={k === agent.scores.length - 1 ? 3.5 : 2.5} fill="var(--violet)" stroke="#fff" strokeWidth="1" />
          ))}
        </svg>
      </div>
      <div className="insp__col">
        <span className="caps">Now testing</span>
        <span className="agent__now">{agent.now}</span>
      </div>
      <pre className="code">{agent.code}</pre>
    </Card>
  );
}
// Connection to the agent harness (`harness serve`, proxied under /harness by Vite).
// Same in every world; do not edit per world. See decision 0007.
import { useEffect, useState } from "react";

/** The world server as the harness reaches it (set by vite.config.ts). */
declare const __WORLD_URL__: string;
const WORLD_URL = typeof __WORLD_URL__ === "string" ? __WORLD_URL__ : "http://127.0.0.1:8000";
const OFFLINE_RETRY_MS = 10000;

/** One agent from agents.toml. */
export interface AgentInfo { name: string; label: string; color?: string | null; model: string }

/** Who plays the world, from `state.play` (added by the base server). */
export interface Play { mode: "you" | "agent"; agent: string | null }

/** Outcome of the last agent run on this world. */
export interface LastRun { agent: string; stopped_by: string; error?: string; agent_steps?: number }

const FALLBACK_COLOR = "#7b61ff";

/** Display name and cursor colour of an agent (also for agents the harness does not list). */
export function agentLook(agents: AgentInfo[], name: string | null): { label: string; color: string } {
  const a = agents.find((x) => x.name === name);
  return { label: a?.label ?? name ?? "Agent", color: a?.color ?? FALLBACK_COLOR };
}

/** Agents the harness offers; `offline` while the harness is not running (retried). */
export function useAgents(): { agents: AgentInfo[]; offline: boolean } {
  const [agents, setAgents] = useState<AgentInfo[]>([]);
  const [offline, setOffline] = useState(false);
  useEffect(() => {
    let alive = true;
    let timer: ReturnType<typeof setTimeout>;
    const load = async () => {
      try {
        const res = await fetch("/harness/agents");
        if (!res.ok) throw new Error(String(res.status));
        const list = (await res.json()) as AgentInfo[];
        if (alive) { setAgents(list); setOffline(false); }
      } catch {
        if (alive) { setOffline(true); timer = setTimeout(load, OFFLINE_RETRY_MS); }
      }
    };
    void load();
    return () => { alive = false; clearTimeout(timer); };
  }, []);
  return { agents, offline };
}

async function post(path: string, body: unknown): Promise<{ ok: boolean; error?: string }> {
  try {
    const res = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    if (res.ok) return { ok: true };
    const detail = await res.json().then((d: { detail?: unknown }) => d.detail).catch(() => null);
    return { ok: false, error: typeof detail === "string" ? detail : `Harness: HTTP ${res.status}` };
  } catch {
    return { ok: false, error: "No connection to the harness (pixi run harness serve)" };
  }
}

/** Let `agent` play from the current week (no reset, fresh budget). */
export function startAgent(agent: string) {
  return post("/harness/run", { world_url: WORLD_URL, agent });
}

/** Stop the agent and take over by hand. Without a harness, unlock the world directly. */
export async function stopAgent() {
  const sent = await post("/harness/stop", { world_url: WORLD_URL });
  if (sent.ok) return sent;
  return post("/api/action", { id: "mode", args: { mode: "you" } });
}

/** How the last agent run on this world ended, or null. */
export async function lastRun(): Promise<LastRun | null> {
  try {
    const res = await fetch(`/harness/status?world_url=${encodeURIComponent(WORLD_URL)}`);
    return res.ok ? ((await res.json()) as { last: LastRun | null }).last : null;
  } catch {
    return null;
  }
}
